// Action plan data contract
// Validates action plans generated by the planner

import { validate } from './validator.js';

export const PLAN_SCHEMA = {
  planId: {
    type: 'string',
    required: true,
  },
  incidentId: {
    type: 'string',
    required: true,
  },
  goal: {
    type: 'string',
    required: true,
  },
  action: {
    type: 'string',
    required: true,
    enum: ['OBSERVE', 'WAIT', 'RETRY', 'REROUTE', 'REROUTE_TRAFFIC', 'IMMEDIATE_REROUTE', 'GRADUAL_SHIFT', 'SWITCH_NODE', 'ISOLATE_NODE', 'RESTART_SERVICE', 'ESCALATE', 'NONE'],
  },
  sourceNodeId: {
    type: 'number',
    required: false,
  },
  targetNodeId: {
    type: 'number',
    required: false,
  },
  candidates: {
    type: 'array',
    required: false,
  },
  expectedOutcome: {
    type: 'object',
    required: false,
  },
  risk: {
    type: 'number',
    required: false,
    min: 0,
    max: 100,
  },
  confidence: {
    type: 'number',
    required: false,
    min: 0,
    max: 1,
  },
  createdAt: {
    type: 'number',
    required: true,
  },
  status: {
    type: 'string',
    required: true,
    enum: ['READY', 'FAILED', 'PENDING', 'EXECUTED', 'CANCELLED'],
  },
};

/**
 * Validate action plan
 * @param {object} plan - Plan data
 * @returns {object} - Validated plan
 * @throws {ValidationError}
 */
export function validatePlan(plan) {
  return validate(plan, PLAN_SCHEMA, 'plan');
}
